-- Agent tool-call failure diagnosis
-- ONESHOT INSTALLER FORMAT 3
--
-- Nothing to edit. Press Run All.
--
-- What happens: this looks for your Agent tool calls tables
-- (metadata only, using semantic views, Cortex Sense when enabled, and one small AI call),
-- builds the app in its own schema, and stops.
-- No source rows are processed until you press LIMITED in the app.
-- If no suitable table is visible to your role, it stops before building
-- the app and says which tables it needs. Once installed, running this
-- file again changes nothing.
--
-- Uses the worksheet's current warehouse. Installs into database ONESHOT
-- (created if needed), or the worksheet's database if your role cannot create one.
-- A launcher may SET AGENT_PRESELECTED above this file to propose a source:
-- Discovery offers that source first and never binds it. You choose in the app.

EXECUTE IMMEDIATE $$
DECLARE
  phase_name VARCHAR DEFAULT 'Start';
  payload VARIANT;
  result_rows RESULTSET;
BEGIN
  payload := PARSE_JSON(DECOMPRESS_STRING(TO_BINARY('', 'BASE64'), 'ZLIB'));
  -- A rerun in the same worksheet session must not inherit an earlier outcome.
  EXECUTE IMMEDIATE 'SET (AGENT_INSTALL_STATE, AGENT_INSTALL_ERROR) = (''STARTING'', NULL)';
  LET phase_index INTEGER := 0;
  WHILE (:phase_index < ARRAY_SIZE(:payload:phases)) DO
    LET current_phase VARIANT := GET(:payload:phases, :phase_index);
    phase_name := current_phase:name::VARCHAR;
    IF (NOT ((current_phase:bound::BOOLEAN AND GETVARIABLE('AGENT_INSTALL_STATE') = 'AWAITING_REVIEW')
             OR (current_phase:fresh::BOOLEAN AND GETVARIABLE('AGENT_INSTALL_STATE') = 'REINSTALLING'))) THEN
      LET phase_sql VARCHAR := current_phase:sql::VARCHAR;
      result_rows := (EXECUTE IMMEDIATE :phase_sql);
      IF (GETVARIABLE('AGENT_INSTALL_STATE') = 'ALREADY_INSTALLED') THEN
        RETURN TABLE(result_rows);
      END IF;
    END IF;
    phase_index := :phase_index + 1;
  END WHILE;
  RETURN TABLE(result_rows);
EXCEPTION
  WHEN OTHER THEN
    LET failure VARCHAR := COALESCE(GETVARIABLE('AGENT_INSTALL_ERROR'), SQLERRM);
    LET failure_code INTEGER := SQLCODE;
    result_rows := (SELECT 'INSTALLATION_FAILED' AS STATUS, :phase_name AS FAILED_STEP, :failure AS ERROR,
      :failure_code AS ERROR_CODE, 'Nothing outside the installation schema was changed. Fix the reported problem, then Run All again; it replaces this unfinished attempt.' AS NEXT_STEP);
    RETURN TABLE(result_rows);
END;
$$;
